def plan_day_ahead(ctx):
    """Economic opportunity-cost BESS planning and DA market bidding."""
    bess, rules, fcast = ctx["bess"], ctx["rules"], ctx["forecast"]
    p50 = fcast["price_jpy_kwh"]["p50"]
    p90 = fcast["price_jpy_kwh"]["p90"]
    margin = fcast["reserve_margin_p50"]
    rte = bess["rte"]
    eta_ch = bess.get("eta_charge", math.sqrt(rte))
    eta_dis = bess.get("eta_discharge", math.sqrt(rte))
    deg_kwh = bess.get("degradation_jpy_per_mwh", 8000.0) / 1000.0
    mean_p50 = sum(p50) / SLOTS

    # Discharge valuation incorporating reserve margin tightness
    p_eval = [
        p50[t] + max(0.0, (0.12 - margin[t]) / 0.12) * (p90[t] - p50[t])
        for t in range(SLOTS)
    ]

    # Pre-sort candidate actions by net profit per unit volume
    candidates = []
    for c in range(SLOTS):
        for d in range(SLOTS):
            if c != d:
                profit = p_eval[d] - p50[c] / rte - deg_kwh
                if profit > 0.1:
                    candidates.append((profit, "pair", c, d))

    for d in range(SLOTS):
        profit = p_eval[d] - deg_kwh - mean_p50 / eta_dis
        if profit > 0.1:
            candidates.append((profit, "dis", None, d))

    for c in range(SLOTS):
        profit = mean_p50 * eta_ch - p50[c]
        if profit > 0.1:
            candidates.append((profit, "ch", c, None))

    candidates.sort(key=lambda x: x[0], reverse=True)

    # Multi-pass greedy allocation on discrete steps
    step_mw = 5.0
    plan = [0.0] * SLOTS
