    fcast_ha = ctx["forecast_ha"]
    forecast_mwh = fcast_ha["net_load_mwh"]
    da_net = ctx["position_mwh"]["da_net"]
    planned_mw = bess["planned_mw"]
    soc = bess["soc_mwh"]
    discharged = bess["discharged_today_mwh"]

    # Baseline planned BESS dispatch
    baseline_mw = feasible_mw(planned_mw, soc, bess, discharged)
    gap = forecast_mwh - (da_net + baseline_mw * 0.5)

    # Scarcity risk indicator
    scarcity = fcast_ha.get("reserve_margin", 0.15) < 0.10 or fcast_ha.get("imbalance_scarcity_price_est", 0.0) > 25.0

    # Flexible BESS re-dispatch: reduce charging when short, reduce discharging when long, or respond to scarcity
    target_mw = baseline_mw
    if gap > 0:
        if baseline_mw < 0:
            target_mw = min(0.0, baseline_mw + gap / 0.5)
        elif scarcity:
            target_mw = baseline_mw + gap / 0.5
    elif gap < 0:
        if baseline_mw > 0:
            target_mw = max(0.0, baseline_mw + gap / 0.5)
        elif soc < bess["soc_max_mwh"] * 0.85:
            target_mw = baseline_mw + gap / 0.5

    adj_mw = feasible_mw(target_mw, soc, bess, discharged)
    rem_gap = forecast_mwh - (da_net + adj_mw * 0.5)

    orders = []
    signed_trade_mwh = 0.0

    if abs(rem_gap) >= rules["lot_mwh"]:
        q = lots(abs(rem_gap), rules)
        if q >= rules["lot_mwh"]:
            if rem_gap > 0:
                limit = min(rules["price_cap"], idm["best_ask"] + (3.0 if scarcity else 1.5))
                orders.append({"side": "buy", "qty_mwh": q, "limit_jpy_kwh": limit})
                signed_trade_mwh = q
            else:
                limit = max(rules["price_floor"], idm["best_bid"] - (3.0 if scarcity else 1.5))
                orders.append({"side": "sell", "qty_mwh": q, "limit_jpy_kwh": limit})
                signed_trade_mwh = -q

    # Fine-tune BESS dispatch to absorb lot-rounding residuals for near-zero final imbalance
    final_target_mw = (forecast_mwh - da_net - signed_trade_mwh) / 0.5
    final_mw = feasible_mw(final_target_mw, soc, bess, discharged)

    return {"orders": orders, "bess_mw": final_mw}

