def adjust_intraday(ctx):
    """Plan-based balancing: submit lot-matched IDM orders and fine-tune BESS MW to absorb residuals."""
    bess, rules, idm = ctx["bess"], ctx["rules"], ctx["intraday"]
    forecast = ctx["forecast_ha"]["net_load_mwh"]
    da_net = ctx["position_mwh"]["da_net"]
    soc = bess["soc_mwh"]
    discharged = bess["discharged_today_mwh"]
    planned_mw = bess["planned_mw"]

    base_mw = feasible_mw(planned_mw, soc, bess, discharged)
    gap = forecast - (da_net + base_mw * 0.5)
    tol = tolerance_mwh(forecast, rules)

    orders = []
    signed_idm_mwh = 0.0
    if abs(gap) > 0.6 * tol:
        target_idm = gap - math.copysign(0.3 * tol, gap)
        if target_idm >= rules["lot_mwh"]:
            q = lots(target_idm, rules)
            if q >= rules["lot_mwh"]:
                ask_limit = min(rules["price_cap"], idm["best_ask"] + 2.0)
                orders.append({"side": "buy", "qty_mwh": q, "limit_jpy_kwh": ask_limit})
                signed_idm_mwh = q
        elif target_idm <= -rules["lot_mwh"]:
            q = lots(-target_idm, rules)
            if q >= rules["lot_mwh"]:
                bid_limit = max(rules["price_floor"], idm["best_bid"] - 2.0)
                orders.append({"side": "sell", "qty_mwh": q, "limit_jpy_kwh": bid_limit})
                signed_idm_mwh = -q

    rem_gap = forecast - (da_net + base_mw * 0.5 + signed_idm_mwh)
    target_bess_mw = base_mw + rem_gap / 0.5
    final_bess_mw = feasible_mw(target_bess_mw, soc, bess, discharged)

    return {"orders": orders, "bess_mw": final_bess_mw}

