    bess, rules, fcast = ctx["bess"], ctx["rules"], ctx["forecast"]
    p50 = fcast["price_jpy_kwh"]["p50"]
    p90 = fcast["price_jpy_kwh"]["p90"]
    margin = fcast.get("reserve_margin_p50", [0.15] * SLOTS)
    rte = bess["rte"]
    deg_kwh = bess.get("degradation_jpy_per_mwh", 8000.0) / 1000.0
    mean_p50 = sum(p50) / SLOTS

    p_eval = [
        p50[t] + max(0.0, (0.13 - margin[t]) / 0.13) * (p90[t] - p50[t])
        for t in range(SLOTS)
    ]

    pairs = []
    for d in range(SLOTS):
        for c in range(SLOTS):
            if c == d:
                continue
            unit_margin = p_eval[d] - p50[c] / rte - deg_kwh
            if unit_margin > 0.02:
                pairs.append((unit_margin, c, d))

    pairs.sort(key=lambda x: x[0], reverse=True)

    best_plan, best_val = _eval_plan([0.0] * SLOTS, bess["soc_mwh"], bess, p_eval, p50, deg_kwh, mean_p50)

    for _pass in range(4):
        for _, c, d in pairs:
            for add_mw in (60.0, 45.0, 30.0, 15.0, 5.0, 2.0, 1.0):
                if best_plan[c] - add_mw < -bess["power_mw"] - 1e-5:
                    continue
                if best_plan[d] + add_mw > bess["power_mw"] + 1e-5:
                    continue
                test_plan = list(best_plan)
                test_plan[c] -= add_mw
                test_plan[d] += add_mw
                clipped, val = _eval_plan(test_plan, bess["soc_mwh"], bess, p_eval, p50, deg_kwh, mean_p50)
                if val > best_val + 1e-4:
                    best_plan, best_val = clipped, val
                    break

    net = fcast["net_load_mwh_p50"]
    bids = []
    for t in range(SLOTS):
        qty_net = net[t] - best_plan[t] * 0.5
        if qty_net > 0:
            q = lots(qty_net, rules)
            if q >= rules["lot_mwh"]:
                bids.append({"slot": t + 1, "side": "buy", "qty_mwh": q, "limit_jpy_kwh": rules["price_cap"]})
        elif qty_net < 0:
            q = lots(-qty_net, rules)
            if q >= rules["lot_mwh"]:
                bids.append({"slot": t + 1, "side": "sell", "qty_mwh": q, "limit_jpy_kwh": rules["price_floor"]})

    return {"bids": bids, "bess_plan_mw": best_plan}


def adjust_intraday(ctx):
    """Follow BESS plan; selectively execute intraday trades when forecast gap exceeds target threshold."""
    bess, rules, idm = ctx["bess"], ctx["rules"], ctx["intraday"]
    mw = feasible_mw(bess["planned_mw"], bess["soc_mwh"], bess, bess["discharged_today_mwh"])
    forecast = ctx["forecast_ha"]["net_load_mwh"]
    position = ctx["position_mwh"]["da_net"] + mw * 0.5
    gap = forecast - position
    tol = tolerance_mwh(forecast, rules)

    target_band = 0.70 * tol
    qty = 0.0
    if abs(gap) > target_band:
        qty = gap - math.copysign(target_band, gap)

    orders = []
    if qty >= rules["lot_mwh"]:
        q = lots(qty, rules)
        if q >= rules["lot_mwh"]:
            orders.append({"side": "buy", "qty_mwh": q, "limit_jpy_kwh": min(rules["price_cap"], idm["best_ask"] + 2.0)})
    elif qty <= -rules["lot_mwh"]:
        q = lots(-qty, rules)
        if q >= rules["lot_mwh"]:
            orders.append({"side": "sell", "qty_mwh": q, "limit_jpy_kwh": max(rules["price_floor"], idm["best_bid"] - 2.0)})

    return {"orders": orders, "bess_mw": mw}

def _eval_plan(plan_mw, soc0, bess, p_eval, p50, deg_kwh, mean_p50):
    clipped = clip_plan(plan_mw, soc0, bess)
    soc = soc0
    val = 0.0
    for t in range(SLOTS):
        mw = clipped[t]
        if mw > 0:
            val += mw * 0.5 * (p_eval[t] - deg_kwh)
        elif mw < 0:
            val += mw * 0.5 * p50[t]
        soc = soc_after(soc, mw, bess)
    val += (soc - soc0) * bess["eta_discharge"] * mean_p50
    return clipped, val


